/* ---------- interactive theory ---------- */
function onTheory(root){
  const w=root.querySelector('#w-calc');
  if(w){w.innerHTML=`<b>Калькулятор прироста: подвигай «краны»</b>
    <label>Рождаемость: <output id="cr"></output><input type="range" id="cR" min="5" max="45" step="1" value="10"></label>
    <label>Смертность: <output id="cd"></output><input type="range" id="cD" min="5" max="35" step="1" value="13"></label>
    <label>Сальдо миграции: <output id="cm"></output><input type="range" id="cM" min="-10" max="10" step="1" value="2"></label>
    <div id="cpic" class="fig"></div><div id="ctx" style="text-align:center;line-height:1.7"></div>`;
    const g=id=>w.querySelector('#'+id);const u=()=>{const r=+g('cR').value,d=+g('cD').value,m=+g('cM').value;g('cr').textContent=r+' ‰';g('cd').textContent=d+' ‰';g('cm').textContent=(m>0?'+':'')+m+' ‰';
      const e=r-d,t=e+m;let s='';const P0=100;const ys=[0,10,20,30,40,50];ys.forEach((y,i)=>{const v=P0*Math.pow(1+t/1000,y);const h=Math.max(4,Math.min(145,75+60*Math.log2(v/100)));const x=30+i*50;s+=RC(x,170-h,32,h,{f:t>=0?'var(--ok)':'var(--bad)',fo:0.6,rx:3})+TX(x+16,165-h,N(Math.round(v)),{fs:10.5})+TX(x+16,186,y?'+'+y:'сейчас',{fs:10,wt:500,c:'var(--muted)'});});
      g('cpic').innerHTML=SV(330,192,s+TX(165,12,'Город: сейчас 100 тыс. — сколько тыс. будет через N лет',{fs:11,c:'var(--muted)'}),'Изменение численности',440);
      g('ctx').innerHTML=`ЕП = ${r} − ${d} = <span class="out">${e>0?'+':''}${N(e)} ‰</span> ${e<0?'(убыль)':''} · общий прирост = ${N(e)} ${m>=0?'+':'−'} ${Math.abs(m)} = <span class="out">${t>0?'+':''}${N(t)} ‰</span><br><span class="small">${r>=30&&d>=20?'Похоже на традиционный тип воспроизводства.':r<=14&&d<=14?'Похоже на современный тип.':''} ${t>0?'Население растёт'+(t>=5?`, удвоится примерно за ${Math.round(700/t)} лет (правило 70).`:'.'):t<0?'Население сокращается.':'Население стабильно.'}</span>`;};
    ['cR','cD','cM'].forEach(id=>g(id).oninput=u);u();}
  const p=root.querySelector('#w-pyr');
  if(p){const ks=Object.keys(PYR);let cur=ks[0];p.innerHTML=`<b>Пирамида: выбери тип и сравни основание с серединой</b><div id="pb" style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0">${ks.map(k=>`<button class="btn ghost" data-k="${k}" style="padding:6px 10px;font-size:14px">${k}</button>`).join('')}</div><div id="pp" class="fig"></div><div id="pt" style="text-align:center;line-height:1.6"></div>`;
    const D={'прогрессивный (растущий)':'Детей больше всех — население растёт. Так в странах Африки и в России 100 лет назад; сейчас ближе всего — Дагестан, Тыва.','стационарный (стабильный)':'Поколения примерно равны — численность почти не меняется.','регрессивный (стареющий)':'Детей меньше, чем людей среднего возраста — население стареет и в будущем сократится. Похоже на большинство регионов России и страны Европы.'};
    const u=()=>{p.querySelector('#pp').innerHTML=pyrSVG(PYR[cur],{wd:380,fem:true});p.querySelector('#pt').innerHTML=`<span class="out">${cur}</span>: ${D[cur]}`;p.querySelectorAll('#pb button').forEach(b=>b.className='btn'+(b.dataset.k===cur?'':' ghost'));};
    p.querySelector('#pb').addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(b){cur=b.dataset.k;u();}});u();}
}
